SELECT 100.0 * (
    COUNT(CASE WHEN strftime('%Y', Date) = '2010' THEN 1 END)
    - COUNT(CASE WHEN strftime('%Y', Date) = '2011' THEN 1 END)
) / NULLIF(COUNT(*), 0) AS difference_percentage_points
FROM badges
WHERE Name = 'Student';

SELECT d.nationality
FROM drivers AS d
WHERE d.driverId IN (
    SELECT q.driverId
    FROM qualifying AS q
    WHERE q.q3 = (
        SELECT MIN(NULLIF(q3, ''))
        FROM qualifying
    )
);

SELECT ROUND(100.0 * COUNT(CASE WHEN NOT EXISTS (
    SELECT 1
    FROM member AS m
    WHERE m.link_to_major = a.major_id
) THEN 1 END) / COUNT(*), 2) AS percentage
FROM major AS a;

SELECT MAX(CAST(NULLIF(RNP, 'negative') AS NUMERIC)) AS highest_anti_rnp
FROM Laboratory
WHERE CRE < 1.5;

SELECT COUNT(DISTINCT ID) AS patient_count
FROM Patient
WHERE Diagnosis COLLATE NOCASE = 'psoriatic arthritis';
